export type ParsedCreateIntentByAgentInstruction<
  TProgram extends string = typeof INTENT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    agent: TAccountMetas[0];
    owner: TAccountMetas[1];
    mandate: TAccountMetas[2];
    config: TAccountMetas[3];
    userState: TAccountMetas[4];
    intent: TAccountMetas[5];
    inputMint: TAccountMetas[6];
    outputMint: TAccountMetas[7];
    ownerInput: TAccountMetas[8];
    receiver: TAccountMetas[9];
    receiverAuthority: TAccountMetas[10];
    vault: TAccountMetas[11];
    delegate: TAccountMetas[12];
    inputTokenProgram: TAccountMetas[13];
    outputTokenProgram: TAccountMetas[14];
    treasury: TAccountMetas[15];
    systemProgram: TAccountMetas[16];
    eventAuthority: TAccountMetas[17];
    program: TAccountMetas[18];
  };
  data: CreateIntentByAgentInstructionData;
};

export function parseCreateIntentByAgentInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCreateIntentByAgentInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 19) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 19,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      agent: getNextAccount(),
      owner: getNextAccount(),
      mandate: getNextAccount(),
      config: getNextAccount(),
      userState: getNextAccount(),
      intent: getNextAccount(),
      inputMint: getNextAccount(),
      outputMint: getNextAccount(),
      ownerInput: getNextAccount(),
      receiver: getNextAccount(),
      receiverAuthority: getNextAccount(),
      vault: getNextAccount(),
      delegate: getNextAccount(),
      inputTokenProgram: getNextAccount(),
      outputTokenProgram: getNextAccount(),
      treasury: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getCreateIntentByAgentInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
